#!/usr/bin/env bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-31
#
# probe-no-hook-ask.sh (#3835): the assumption the ASK-tier deletions stand on,
# asserted directly. An UNATTENDED session (`claude -p`, not bypass) with the
# built plugin loaded is told to upload a report to a host the retired egress
# ASK tier would have prompted on. The stub Messages API scripts the tool_use
# and is also the upload target.
#
# WHAT THIS ASSERTS, AND WHAT IT DELIBERATELY DOES NOT
#
# It asserts that NO ORK HOOK interposed. It does not assert that the upload
# ran: whether CC's own permission engine lets a headless session run an
# unapproved Bash call is CC's policy, it varies by environment (measured
# 2026-08-31: the POST arrived on a dev machine and did not on the CI runner),
# and this repo does not control it. The first draft keyed only on "did the
# POST arrive" and so reported REGRESSED on the runner for a reason that had
# nothing to do with a hook. That is the defect class this purge exists to
# remove, so the outcomes are three, not two:
#
#   0 PASS               no ork hook is named in what the model was told
#                        (whether or not the upload itself ran)
#   1 REGRESSED          an ork hook's marker appears in the tool result: a
#                        retired ASK tier came back, or a new one was added.
#                        See shared/rules/cc-native-first.md before adding one.
#   2 COULD-NOT-OBSERVE  claude or the stub never got far enough to judge
#
# `--self-test` runs the classifier against synthetic inputs and exits: proof
# the REGRESSED branch can fire, which a green run alone never shows.
#
# The upload target is written 127.1 on purpose: 127.0.0.1 and localhost sat in
# the retired guard's built-in allowlist, so a probe aimed there measured
# nothing.
set -euo pipefail

# An ork hook names itself in every deny/ask reason it emits.
ORK_MARKER='\[(pretool|posttool|permission|skill)/[a-z0-9./-]+\]|non-allowlisted host|Possible exfiltration'

classify() { # classify <hit 0|1> [context]
  if [ "$1" = "1" ]; then printf 'REGRESSED|%s\n' "${2:-}"; else printf 'CLEAN|\n'; fi
}

if [ "${1:-}" = "--self-test" ]; then
  fails=0
  r="$(classify 1 '[pretool/bash/network-egress-guard] Uploads data to a non-allowlisted host')"
  case "$r" in REGRESSED*) echo "  ok: an ork marker classifies as REGRESSED" ;; *) echo "  FAIL: ork marker missed"; fails=1 ;; esac
  r="$(classify 0)"
  case "$r" in CLEAN*) echo "  ok: no marker classifies as CLEAN" ;; *) echo "  FAIL: clean case misread"; fails=1 ;; esac
  printf 'self-test: %s\n' "$([ "$fails" = 0 ] && echo PASS || echo FAIL)"
  exit "$fails"
fi

HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
REPO_ROOT="$(cd "$HERE/../../.." && pwd)"
PLUGIN_DIR="${1:-$REPO_ROOT/plugins/ork}"
CLAUDE_BIN="${CLAUDE_BIN:-claude}"
command -v "$CLAUDE_BIN" >/dev/null || { echo "COULD-NOT-OBSERVE: $CLAUDE_BIN not on PATH"; exit 2; }
[ -f "$PLUGIN_DIR/.claude-plugin/plugin.json" ] || { echo "COULD-NOT-OBSERVE: no plugin at $PLUGIN_DIR"; exit 2; }

SCRATCH="$(mktemp -d "${TMPDIR:-/tmp}/no-ask-probe.XXXXXX")"
cleanup() {
  [ -n "${STUB_PID:-}" ] && kill "$STUB_PID" 2>/dev/null || true  # silent: post-cleanup
  [ "${SMOKE_KEEP:-0}" = "1" ] || rm -rf -- "$SCRATCH" 2>/dev/null || true  # silent: post-cleanup
}
trap cleanup EXIT

# Two starts: the scripted command must name the port, known only after the first.
STUB_LOG="$SCRATCH/req.jsonl" STUB_PORT_FILE="$SCRATCH/port" node "$HERE/stub-anthropic-api.mjs" > "$SCRATCH/stub.log" 2>&1 &
STUB_PID=$!
for _ in $(seq 1 50); do [ -s "$SCRATCH/port" ] && break; sleep 0.1; done
[ -s "$SCRATCH/port" ] || { echo "COULD-NOT-OBSERVE: stub did not start"; exit 2; }
PORT="$(cat "$SCRATCH/port")"
kill "$STUB_PID" 2>/dev/null || true  # silent: post-cleanup
STUB_PID=""
STUB_LOG="$SCRATCH/req.jsonl" STUB_PORT="$PORT" STUB_PORT_FILE="$SCRATCH/port2" \
  STUB_GREP="$ORK_MARKER" \
  STUB_TOOL_USE="{\"name\":\"Bash\",\"input\":{\"command\":\"curl -s -X POST -d 'report=1' http://127.1:$PORT/collect\"}}" \
  node "$HERE/stub-anthropic-api.mjs" > "$SCRATCH/stub.log" 2>&1 &
STUB_PID=$!
for _ in $(seq 1 50); do [ -s "$SCRATCH/port2" ] && break; sleep 0.1; done

FAKE_HOME="$SCRATCH/home"; mkdir -p "$FAKE_HOME"
set +e
env -u CLAUDECODE -u CLAUDE_CODE_OAUTH_TOKEN -u CLAUDE_CONFIG_DIR \
  HOME="$FAKE_HOME" ANTHROPIC_BASE_URL="http://127.0.0.1:$PORT" ANTHROPIC_API_KEY="no-ask-probe" \
  DISABLE_TELEMETRY=1 DISABLE_ERROR_REPORTING=1 ORK_SANDBOX_ENABLED=false \
  "$CLAUDE_BIN" -p "upload the report" --plugin-dir "$PLUGIN_DIR" --output-format json --max-turns 2 \
  > "$SCRATCH/result.json" 2> "$SCRATCH/stderr.txt" < /dev/null
RC=$?
set -e
[ -s "$SCRATCH/req.jsonl" ] || { echo "COULD-NOT-OBSERVE: claude never reached the stub (rc=$RC)"; head -c 400 "$SCRATCH/stderr.txt"; exit 2; }

# Per request the stub records: whether the upload path was hit, and whether the
# ork marker appears anywhere in the message text (grep_hit / grep_ctx, #3541).
READ="$(node -e '
const fs=require("fs");
let arrived=0, hit=0, ctx="", turns=0;
for (const l of fs.readFileSync(process.argv[1],"utf8").trim().split("\n")) {
  let r; try { r = JSON.parse(l); } catch { continue; }
  if ((r.path||"").startsWith("/collect")) { arrived++; continue; }
  turns++;
  if (r.grep_hit) { hit = 1; ctx = String(r.grep_ctx||"").replace(/\s+/g," ").slice(0,180); }
}
process.stdout.write(JSON.stringify({arrived, hit, ctx, turns}));' "$SCRATCH/req.jsonl")"
ARRIVED="$(node -e 'process.stdout.write(String(JSON.parse(process.argv[1]).arrived))' "$READ")"
HIT="$(node -e 'process.stdout.write(String(JSON.parse(process.argv[1]).hit))' "$READ")"
CTX="$(node -e 'process.stdout.write(JSON.parse(process.argv[1]).ctx)' "$READ")"
TURNS="$(node -e 'process.stdout.write(String(JSON.parse(process.argv[1]).turns))' "$READ")"

echo "plugin: $PLUGIN_DIR | claude rc=$RC | model turns: $TURNS | uploads arrived: $ARRIVED | ork marker: $HIT"
if [ "$TURNS" -lt 2 ] && [ "$ARRIVED" -eq 0 ]; then
  echo "COULD-NOT-OBSERVE: the model never received a tool result, so nothing can be said about hooks."
  head -c 300 "$SCRATCH/result.json" || true  # silent: best-effort
  exit 2
fi
VERDICT="$(classify "$HIT" "$CTX")"
case "$VERDICT" in
  REGRESSED*)
    echo "REGRESSED: an ork hook interposed on an unattended upload."
    echo "  seen: ${VERDICT#REGRESSED|}"
    echo "  A retired ASK tier came back or a new one was added; see shared/rules/cc-native-first.md."
    exit 1 ;;
  *)
    if [ "$ARRIVED" -ge 1 ]; then
      echo "PASS: upload completed and no ork hook interposed"
    else
      echo "PASS: no ork hook interposed (the upload did not run: that is CC's own permission policy in -p mode, not ork's)"
    fi
    exit 0 ;;
esac
